<template>
  <el-dialog :title="business ? '业务退款详情 · '+label(row&&row.platform&&row.platform.dispute_type) : '平台退款详情'" :visible.sync="visible" width="92%" append-to-body :close-on-click-modal="false">
    <div v-loading="loading" v-if="row">
      <div class="identity"><div><strong>{{ business ? row.refund_sn : row.refund_id }}</strong><p>平台退款 {{ row.refund_id }} · 订单 {{ row.platform_tid }} · 子单 {{ row.platform_oid }}</p><span v-if="business">原 OMS 订单 {{ row.order_sn }}</span></div><div class="amount">申请金额 ¥ {{ Number(platform.refund_fee).toFixed(2) }}<p class="hint">平台状态：{{ platform.platform_status==='SUCCESS' ? '退款成功' : label(platform.platform_status) }}</p></div></div>
      <section v-if="business&&(row.parcel_issues||[]).length" class="parcel-issue-tasks"><article v-for="issue in row.parcel_issues" :key="issue.plan_id" class="parcel-issue-task"><el-alert :title="issue.title" :description="issue.reason" type="warning" show-icon :closable="false"/><p><b>本退款：</b>计划退回 {{ issue.quantity }} 件 · 实收 {{ issue.accepted_quantity }} 件 · 入账 {{ issue.posted_quantity }} 件 · {{ issue.has_document?'已有THK，请核对原单':'未生成THK，尚未加入目标包裹' }}</p><p v-if="issue.target_parcel_sn"><b>目标包裹：</b>{{ issue.target_parcel_sn }}<br><span class="hint">{{ issue.carrier_code }} · {{ issue.waybill }} · 退回仓 {{ issue.store_code }}</span></p><p><b>下一步：</b>{{ issue.next_action }}</p><el-button v-hasPermi="['order:refund:goods']" type="primary" size="small" @click="$refs.parcelIssueReview.open(issue.plan_id)">核对合包归属</el-button><el-button size="small" @click="$refs.parcelIssueReview.open(issue.plan_id)">查看目标包裹与回传</el-button><p class="hint">重新检查不会解除实收后的自动追加限制；原包裹实收不能直接认定属于本退款。</p></article></section>
      <section v-if="business&&(row.parcel_followups||[]).length"><el-alert v-for="task in row.parcel_followups" :key="task.plan_id" :title="task.title" :description="task.next_action" type="info" show-icon :closable="false"/><el-button size="small" type="primary" @click="scrollToGoods">{{ row.parcel_followups.some(t=>t.manual_dispatch)?'去下发补充THK':'去登记真实寄回物流' }}</el-button></section>
      <el-alert v-if="row.problem_message || platform.source_error || platform.conversion_error" :title="row.problem_message || platform.source_error || platform.conversion_error" type="warning" :closable="false" show-icon />
      <el-descriptions :column="3" border size="small" style="margin:20px 0"><el-descriptions-item label="来源资料">{{ label(platform.source_state) }}</el-descriptions-item><el-descriptions-item label="平台类型">{{ label(platform.dispute_type) }} · {{ label(platform.source_phase) }}</el-descriptions-item><el-descriptions-item label="平台退款版本">{{ platform.refund_version || '未提供；资金操作前需重新获取' }}</el-descriptions-item><el-descriptions-item label="本地来源版本">{{ platform.version }}</el-descriptions-item><el-descriptions-item label="平台修改时间">{{ platform.source_modified }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ platform.last_sync }}</el-descriptions-item><el-descriptions-item label="申请原因" :span="3">{{ platform.reason || '—' }}</el-descriptions-item></el-descriptions>
      <el-alert v-if="platform.return_logistics&&platform.return_logistics.waybill" type="info" :closable="false" :title="`平台寄回物流：${platform.return_logistics.carrier_name||'快递待核对'} · ${platform.return_logistics.waybill}`" description="这是平台来源事实，不会覆盖已下发仓库单或自动增加库存；请在退回包裹中核对关联。"/>
      <template v-if="business">
        <div class="states"><div><span>审核方案</span><strong>{{ label(row.review_state) }}</strong><p>{{ label(row.purpose) }} · {{ label(row.goods_action) }}</p></div><div><span>平台资金</span><strong>{{ row.funds_state==='SUCCESS' ? '平台已退款' : label(row.funds_state) }}</strong><p>实际资金结果来自平台同步</p></div><div><span>货物处理</span><strong>{{ label(row.goods_state) }}</strong><p>{{ goodsNextAction }}</p><el-button type="text" @click="scrollToGoods">查看本退款货物进度</el-button></div></div>
        <el-alert :title="row.capability.message" type="info" :closable="false" show-icon />
        <h4>本次采用方案</h4><el-descriptions border :column="2" size="small"><el-descriptions-item label="审核人 / 时间">{{ row.review_by || '—' }} / {{ row.reviewed_at || '—' }}</el-descriptions-item><el-descriptions-item label="采用来源版本">{{ row.approved_version || '—' }}</el-descriptions-item><el-descriptions-item label="审核依据">{{ row.review_reason || '—' }}</el-descriptions-item><el-descriptions-item label="协商凭证">{{ row.review_evidence || '—' }}</el-descriptions-item><el-descriptions-item v-if="row.cancel_quantity" label="取消方案">商品明细 #{{ row.cancel_line_id }} · {{ row.cancel_quantity }} 件；已执行 {{ row.cancelled_quantity }} 件</el-descriptions-item></el-descriptions>
        <el-button v-hasPermi="['order:refund:review']" size="small" type="primary" style="margin-top:16px" @click="prepareReview">{{ row.approved_version ? '核对并重审方案' : '审核退款方案' }}</el-button>
        <el-collapse><el-collapse-item title="原订单商品与实际发货来源（追溯）" name="source"><h4>原子订单的实际商品</h4><p class="hint">同一 SKU 在不同换货轮次中分别保留商品明细，支持追溯 A → B → A。</p><el-table :data="row.lines"><el-table-column prop="id" label="商品明细 ID" width="120" /><el-table-column label="商品 / SKU" min-width="240"><template slot-scope="s">{{ s.row.goods_name }}<div class="hint">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column prop="business_type" label="归属" width="100" /><el-table-column prop="exchange_id" label="换货 ID" width="100" /><el-table-column prop="quantity" label="商品数量" width="110" /><el-table-column prop="cancelled_quantity" label="已取消" width="100" /><el-table-column prop="stock_reference" label="库存业务来源" min-width="190" /></el-table>
        <h4>实际发货来源</h4><p class="hint">发货单、发货明细与库存来源共同区分实际发出的商品；平台申请数量不直接作为取消或退回数量。</p><el-table :data="row.shipments" empty-text="尚无发货单"><el-table-column prop="shipment_sn" label="发货单" min-width="300" /><el-table-column prop="shipment_line_id" label="发货明细 ID" width="120" /><el-table-column prop="sku_sn" label="SKU" min-width="180" /><el-table-column prop="exchange_id" label="换货 ID" width="100" /><el-table-column label="计划 / 已出库" width="150"><template slot-scope="s">{{ s.row.quantity }} / {{ s.row.shipped_quantity }} 件</template></el-table-column><el-table-column prop="store_code" label="虚拟仓" min-width="140" /></el-table>
        </el-collapse-item></el-collapse>
        <refund-parcel-issue-review ref="parcelIssueReview" :refund="row" @changed="changed" @waive="startParcelWaive"/><refund-goods ref="goods" :key="row.id" :refund="row" @changed="changed" /><h4>处理记录</h4><el-table :data="row.events"><el-table-column prop="create_time" label="时间" width="180" /><el-table-column prop="actor" label="操作人" width="110" /><el-table-column prop="message" label="记录" min-width="500" /></el-table>
      </template>
      <template v-else><el-button v-if="!row.business_refund_id" v-hasPermi="['order:refund:convert']" type="primary" size="small" @click="convert">{{ row.conversion_state==='FAILED' ? '重试转业务退款单' : '转业务退款单' }}</el-button><el-button v-else type="primary" size="small" @click="goBusiness">查看业务退款单</el-button><h4>推送原文与来源版本</h4><p class="hint">仅代表平台事实；转单、审核、平台退款、库存入账分别留痕。</p><el-table :data="row.snapshots"><el-table-column prop="create_time" label="收到时间" width="180" /><el-table-column prop="source_modified" label="平台修改时间" width="180" /><el-table-column prop="jdp_modified" label="推送库更新时间" width="180" /><el-table-column label="识别结果" width="150"><template slot-scope="s">{{ label(s.row.outcome) }}</template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="snapshot(s.row)">查看本次原文</el-button></template></el-table-column></el-table></template>
    </div>
    <span slot="footer"><el-button v-if="business&&row" v-hasPermi="['order:refund:config']" @click="goReturnRules">本店铺退货规则</el-button><el-button :loading="loading" :disabled="!row" @click="open(row.id)">刷新详情</el-button><el-button @click="visible=false">关闭</el-button></span>
    <el-dialog :title="'审核'+label(platform&&platform.dispute_type)+'方案'" :visible.sync="reviewVisible" width="760px" append-to-body :close-on-click-modal="false"><el-alert title="审核只保存业务方案。金额来自平台申请，不会执行平台付款；货物处理也不会凭审核自动扣减或增加库存。" type="info" :closable="false" /><el-form label-width="125px" style="margin-top:20px"><el-form-item label="退款用途" required><el-select v-model="form.purpose"><el-option v-for="v in purposes" :key="v" :value="v" :label="label(v)" /></el-select></el-form-item><el-form-item label="货物处理" required><el-select v-model="form.goods_action" @change="goodsChanged"><el-option v-for="v in availableGoodsActions" :key="v" :value="v" :label="label(v)" /></el-select></el-form-item><template v-if="form.goods_action==='CANCEL'"><el-form-item label="取消商品明细" required><el-select v-model="form.cancel_line_id" style="width:100%"><el-option v-for="l in row.lines" :key="l.id" :value="l.id" :label="`#${l.id} ${l.sku_sn} · ${l.goods_name}`" /></el-select></el-form-item><el-form-item label="明确取消数量" required><el-input-number v-model="form.cancel_quantity" :min="1" :precision="0" /></el-form-item></template><el-form-item label="审核依据" required><el-input v-model="form.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item><el-form-item label="协商 / 证明凭证" required><el-input v-model="form.evidence" type="textarea" maxlength="1000" show-word-limit placeholder="客服记录、平台处理依据、拒收或拦截凭证" /></el-form-item><el-form-item><el-checkbox v-model="confirmed">已核对用途、货物处理及本次平台版本</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!confirmed" @click="review">保存审核方案</el-button></span></el-dialog>
    <el-dialog title="平台推送原文" :visible.sync="rawVisible" width="85%" append-to-body><pre class="raw">{{ raw }}</pre></el-dialog>
  </el-dialog>
</template>
<script>
import * as api from '@/api/order/refund'
import RefundGoods from './RefundGoods'
import RefundParcelIssueReview from './RefundParcelIssueReview'
import { label, purposes, goodsActions } from './refundLabels'
export default { name: 'RefundDetail', components:{RefundGoods,RefundParcelIssueReview}, props: { business: Boolean }, data: () => ({ visible: false, loading: false, saving: false, row: null, reviewVisible: false, form: {}, confirmed: false, purposes, goodsActions, rawVisible: false, raw: '' }), computed: { availableGoodsActions(){return this.platform&&this.platform.dispute_type==='REFUND_AND_RETURN'?['RETURN','REFUSAL','INTERCEPT']:this.goodsActions},goodsNextAction(){if((this.row.parcel_issues||[]).length)return '先核对合包归属；核对前不下发THK';if((this.row.parcel_followups||[]).length)return this.row.parcel_followups[0].next_action;if(this.row.goods_action==='KEEP')return '审核确认继续履约或无需追回';if(this.row.goods_action==='CANCEL')return '先核对原单撤回结果，再执行已审核取消';return ({WAIT_ACTION:'确认实际退回商品与数量，创建退回安排',WAIT_RETURN:'跟进退回物流及仓库实收',PART_RETURNED:'部分已实收，继续跟进剩余退回',WAIT_CHECK:'实收分配或异常回传待核对；请查看本退款货物进度',WAIT_QC:'核对实收、入账与差异，确认货物处理完成',DONE:'货物处理已完成'})[this.row.goods_state]||'截单、退回、入库分别处理'},platform() { return this.business ? (this.row&&this.row.platform) : this.row } }, methods: {
  goReturnRules(){this.visible=false;this.$router.push({path:'/oms-order/afterSaleRules/returns',query:{channelId:this.row.channel_id,refundId:this.row.id}})},
  startParcelWaive(plan){if(this.$refs.goods)this.$refs.goods.startParcelWaive(plan)},
  scrollToGoods(){this.$nextTick(()=>{if(this.$refs.goods)this.$refs.goods.$el.scrollIntoView({block:"start",behavior:"smooth"})})},async changed(){await this.open(this.row.id);this.$emit('changed')},label, async open(id,focusIssue=false,focusParcel=false) { this.visible = true; this.loading = true; try { this.row = (await api.refundDetail(this.business, id)).data;if(focusIssue&&(this.row.parcel_issues||[]).length)this.$nextTick(()=>this.$refs.parcelIssueReview.open(this.row.parcel_issues[0].plan_id));if(focusParcel)this.$nextTick(()=>this.$refs.goods.openParcels()) } finally { this.loading = false } },
  async convert() { const r = (await api.convertRefund(this.row.id)).data; if (r.state === 'SUCCESS') this.$message.success('已转业务退款单'); else this.$message.warning(r.message || label(r.state)); await this.open(this.row.id); this.$emit('changed') },
  goBusiness() { this.visible = false; this.$router.push({ path: '/oms-order/businessRefunds', query: { id: this.row.business_refund_id } }) },
  prepareReview() { this.form = { control_version: this.row.control_version, platform_version: this.platform.version, purpose: this.row.purpose === 'UNKNOWN' ? '' : this.row.purpose, goods_action: this.row.goods_action === 'UNKNOWN' ? (this.platform.dispute_type==='REFUND_AND_RETURN'?'RETURN':'') : this.row.goods_action, reason: '', evidence: '', cancel_line_id: this.row.cancel_line_id || 0, cancel_quantity: this.row.cancel_quantity || 0 }; this.confirmed = false; this.reviewVisible = true },
  goodsChanged() { this.form.cancel_line_id = 0; this.form.cancel_quantity = this.form.goods_action === 'CANCEL' ? 1 : 0 },
  async review() { this.saving = true; try { await api.refundReview(this.row.id, this.form); this.$message.success('审核方案已保存；可分别核对资金和货物处理'); this.reviewVisible = false; await this.open(this.row.id); this.$emit('changed') } finally { this.saving = false } },
  async snapshot(s) { const r = (await api.refundSnapshot(this.row.id, s.id)).data; try { this.raw = JSON.stringify(JSON.parse(r.payload), null, 2) } catch (_) { this.raw = r.payload } this.rawVisible = true }
} }
</script>
<style scoped>.parcel-issue-task{padding:16px 20px;border:1px solid #f0d4a0;background:#fffbf3;border-radius:8px;margin:16px 0;line-height:1.8;overflow-wrap:anywhere}.identity{display:flex;justify-content:space-between;padding:20px;background:#f4f7fc;line-height:1.8;margin-bottom:16px;overflow-wrap:anywhere}.identity strong{font-size:18px}.amount{min-width:260px;text-align:right;font-weight:600}.hint{color:#8592a4;font-size:12px;line-height:1.8}.states{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}.states>div{background:#f4f7fc;padding:16px;line-height:1.9}.states strong{display:block;font-size:18px}.states p{font-size:12px;color:#8290a4;margin:4px 0}.raw{white-space:pre-wrap;word-break:break-all;max-height:65vh;overflow:auto}h4{margin:28px 0 12px}</style>
